int lego_usb_tower_probe(struct usb_interface *interface, const struct usb_device_id *id) {
    struct usb_device *udev = interface_to_usbdev(interface);
    struct lego_usb_tower_device *dev;
    int retval = -ENOMEM;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        goto error;

    spin_lock_init(&dev->lock);
    init_waitqueue_head(&dev->wait);

    if (!(dev->interrupt = usb_find_int_in_endpoint(udev->actconf->interface[0]->altsetting))) {
        dev_err(&interface->dev, "no interrupt endpoint found\n");
        goto error;
    }

    dev->read_urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!dev->read_urb)
        goto error;

    dev->read_buffer = kmalloc(USB_BUFFER_SIZE, GFP_KERNEL);
    if (!dev->read_buffer)
        goto error;

    usb_fill_int_urb(dev->read_urb, udev, usb_rcvintpipe(udev, dev->interrupt->desc.bEndpointAddress),
                     dev->read_buffer, USB_BUFFER_SIZE, lego_usb_tower_read_irq, dev, dev->interrupt->desc.bInterval);

    dev->write_urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!dev->write_urb)
        goto error;

    dev->write_buffer = kmalloc(USB_BUFFER_SIZE, GFP_KERNEL);
    if (!dev->write_buffer)
        goto error;

    usb_fill_int_urb(dev->write_urb, udev, usb_sndintpipe(udev, dev->interrupt->desc.bEndpointAddress),
                     dev->write_buffer, USB_BUFFER_SIZE, lego_usb_tower_write_irq, dev, dev->interrupt->desc.bInterval);

    if (lego_usb_get_firmware_version(udev, &dev->fw_version)) {
        dev_err(&interface->dev, "failed to read firmware version\n");
        goto error;
    }

    dev_info(&interface->dev, "LEGO USB Tower firmware version: %d.%d\n",
             dev->fw_version.major, dev->fw_version.minor);

    usb_set_intfdata(interface, dev);
    return 0;

error:
    if (dev) {
        kfree(dev->read_buffer);
        usb_free_urb(dev->read_urb);
        kfree(dev->write_buffer);
        usb_free_urb(dev->write_urb);
        kfree(dev);
    }
    return retval;
}

int lego_usb_tower_init(struct usb_interface *interface, const struct usb_device_id *id)
{
    struct usb_device *dev = interface_to_usbdev(interface);
    struct lego_usb_tower *t;
    int retval = -ENOMEM;

    t = kzalloc(sizeof(*t), GFP_KERNEL);
    if (!t)
        goto error;

    spin_lock_init(&t->lock);

    t->interface = interface;
    t->dev = dev;
    t->id = id;

    t->interrupt = usb_find_int_in_endpoint(interface->cur_altsetting);
    if (!t->interrupt) {
        dev_err(&dev->dev, "No interrupt endpoint found\n");
        goto error;
    }

    t->read_buf = kmalloc(LEGOWRT_READ_BUFFER_SIZE, GFP_KERNEL);
    if (!t->read_buf)
        goto error;

    t->write_buf = kmalloc(LEGOWRT_WRITE_BUFFER_SIZE, GFP_KERNEL);
    if (!t->write_buf)
        goto error;

    t->interrupt_urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!t->interrupt_urb)
        goto error;

    usb_fill_int_urb(t->interrupt_urb, dev,
                     usb_rcvintpipe(dev, t->interrupt->desc.bEndpointAddress),
                     t->read_buf, LEGOWRT_READ_BUFFER_SIZE,
                     lego_usb_tower_interrupt_complete, t,
                     t->interrupt->desc.bInterval);

    t->interrupt_urb->transfer_flags |= URB_NO_TRANSFER_AT_CLOSE;

    retval = usb_register_dev(interface, &lego_usb_tower_class);
    if (retval) {
        dev_err(&dev->dev, "usb_register_dev failed with %d\n", retval);
        goto error;
    }

    dev_info(&dev->dev, "Lego USB Tower device initialized with firmware version %d.%d\n",
             t->firmware_version_major, t->firmware_version_minor);

    return 0;

error:
    kfree(t->write_buf);
    kfree(t->read_buf);
    usb_free_urb(t->interrupt_urb);
    kfree(t);
    return retval;
}

#include <linux/usb.h>
#include <linux/slab.h>
#include <linux/module.h>
#include <linux/errno.h>

int lego_usb_tower_probe(struct usb_interface *interface, const struct usb_device_id *id) {
    struct usb_device *udev = interface_to_usbdev(interface);
    struct lego_usb_device *dev;
    int retval = -ENOMEM;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        goto error;

    spin_lock_init(&dev->lock);
    init_waitqueue_head(&dev->wait);

    dev->interface = interface;
    dev->udev = udev;
    usb_set_intfdata(interface, dev);

    dev->interrupt_in = -1;
    dev->interrupt_out = -1;

    int i;
    for (i = 0; i < interface->altsetting->desc.bNumEndpoints; ++i) {
        const struct usb_endpoint_descriptor *ep_desc = &interface->altsetting->endpoint[i].desc;

        if (usb_endpoint_is_int_in(ep_desc)) {
            dev->interrupt_in = i;
        } else if (usb_endpoint_is_int_out(ep_desc)) {
            dev->interrupt_out = i;
        }
    }

    if (dev->interrupt_in == -1 || dev->interrupt_out == -1) {
        dev_err(&interface->dev, "Missing interrupt endpoints.\n");
        goto error;
    }

    dev->read_buffer = kmalloc(LEGO_USB_BUFFER_SIZE, GFP_KERNEL);
    dev->write_buffer = kmalloc(LEGO_USB_BUFFER_SIZE, GFP_KERNEL);
    if (!dev->read_buffer || !dev->write_buffer)
        goto error;

    // Retrieve firmware version (example implementation)
    {
        __u8 fw_version[16];
        int actual;
        int rc = usb_interrupt_msg(udev, usb_rcvintpipe(udev, dev->interrupt_in),
                                   fw_version, sizeof(fw_version), &actual, NULL);
        if (rc < 0) {
            dev_err(&interface->dev, "Failed to retrieve firmware version.\n");
        } else {
            dev_info(&interface->dev, "Firmware version: %*phN\n", sizeof(fw_version), fw_version);
        }
    }

    retval = 0;
    return 0;

error:
    if (dev) {
        kfree(dev->read_buffer);
        kfree(dev->write_buffer);
        kfree(dev);
    }
    return retval;
}

int lego_usb_tower_probe(struct usb_interface *interface, const struct usb_device_id *id) {
    int result;
    struct usb_device *udev = interface_to_usbdev(interface);
    struct lego_usb_tower_device *dev;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    usb_set_intfdata(interface, dev);

    spin_lock_init(&dev->lock);
    init_waitqueue_head(&dev->wait);

    result = usb_find_alt_setting(interface, 0, &dev->alt_setting);
    if (!dev->alt_setting) {
        result = -ENODEV;
        goto error_free_dev;
    }

    dev->interrupt = usb_find_int_out_endpoint(dev->alt_setting);
    if (!dev->interrupt) {
        result = -ENODEV;
        goto error_free_dev;
    }

    dev->read_buffer = kmalloc(LEGOWARE_READ_BUFFER_SIZE, GFP_KERNEL);
    if (!dev->read_buffer) {
        result = -ENOMEM;
        goto error_free_dev;
    }

    dev->write_buffer = kmalloc(LEGOWARE_WRITE_BUFFER_SIZE, GFP_KERNEL);
    if (!dev->write_buffer) {
        result = -ENOMEM;
        goto error_free_read_buffer;
    }

    result = usb_submit_urb(dev->interrupt_urb, GFP_KERNEL);
    if (result)
        goto error_free_write_buffer;

    result = lego_usb_tower_get_firmware_version(udev, dev->firmware_version);
    if (result < 0)
        goto error_free_write_buffer;

    dev_info(&udev->dev, "LEGO USB Tower firmware version: %d.%d\n",
             dev->firmware_version[0], dev->firmware_version[1]);

    dev->interface = interface;
    dev->udev = udev;

    return 0;

error_free_write_buffer:
    kfree(dev->write_buffer);
error_free_read_buffer:
    kfree(dev->read_buffer);
error_free_dev:
    kfree(dev);
    return result;
}

int lego_usb_tower_init(struct usb_interface *interface, const struct usb_device_id *id)
{
    int result = 0;
    struct usb_device *udev = interface_to_usbdev(interface);
    struct lego_usb_dev *dev;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    spin_lock_init(&dev->lock);

    dev->int_in = usb_find_interval(udev, 0, USB_DIR_IN, 0, 0);
    if (!dev->int_in) {
        result = -ENODEV;
        goto error_free_dev;
    }

    dev->int_out = usb_find_interval(udev, 0, USB_DIR_OUT, 0, 0);
    if (!dev->int_out) {
        result = -ENODEV;
        goto error_free_dev;
    }

    dev->read_buf = kmalloc(LEGO_USB_READ_BUF_SIZE, GFP_KERNEL);
    if (!dev->read_buf) {
        result = -ENOMEM;
        goto error_free_dev;
    }

    dev->write_buf = kmalloc(LEGO_USB_WRITE_BUF_SIZE, GFP_KERNEL);
    if (!dev->write_buf) {
        result = -ENOMEM;
        goto error_free_read;
    }

    result = usb_get_string(udev, LEGO_USB_STRING_INDEX, LEGO_USB_LANG_ID,
                            dev->firmware_version, LEGO_USB_FW_VERSION_SIZE);
    if (result < 0)
        dev->firmware_version[0] = '\0';
    else
        dev->firmware_version[result] = '\0';

    usb_set_intfdata(interface, dev);

    result = usb_register_dev(interface, &lego_usb_class);
    if (result) {
        dev_err(&udev->dev, "Failed to register USB device\n");
        goto error_free_write;
    }

    return 0;

error_free_write:
    kfree(dev->write_buf);
error_free_read:
    kfree(dev->read_buf);
